package com.bank.construct;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class AccountConstructionDemo {
    private static final Logger log = Logger.getLogger(AccountConstructionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Full constructor: super(args) runs first, then subclass body.
        SavingsAccount rajesh = new SavingsAccount(
                "SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"), new BigDecimal("0.0650"));
        log.info(() -> "Rajesh: " + rajesh.describe());

        // Convenience constructor: chains via this(...) to the full one,
        // defaulting the interest rate. Validation lives in ONE place.
        SavingsAccount priya = new SavingsAccount(
                "CUR3001", "Priya Sharma", new BigDecimal("250000.00"));
        log.info(() -> "Priya: " + priya.describe());
    }
}

