// Base class with ONLY an args constructor → NO no-arg constructor exists.
// Any subclass MUST call super(args) explicitly or it will not compile.
class Account {
    private static final Logger log = Logger.getLogger(Account.class.getName());
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        if (accountId == null || holderName == null || balance == null) {
            throw new IllegalArgumentException("Account fields must not be null");
        }
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
        log.fine(() -> "Account super() initialized " + accountId);
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amt) { this.balance = this.balance.subtract(amt); }
    void credit(BigDecimal amt) { this.balance = this.balance.add(amt); }
}

// ─── Would be in model/SavingsAccount.java in a real project ───
class SavingsAccount extends Account {
    private static final Logger log = Logger.getLogger(SavingsAccount.class.getName());
    private static final BigDecimal DEFAULT_RATE = new BigDecimal("0.0400");
    private final BigDecimal interestRate;

    // PRIMARY constructor: explicit super(args) MUST be the first statement
    // because Account has no no-arg constructor. All validation lives here.
    SavingsAccount(String accountId, String holderName, BigDecimal balance, BigDecimal interestRate) {
        super(accountId, holderName, balance);     // first statement, runs before body
        if (interestRate == null || interestRate.signum() < 0) {
            throw new IllegalArgumentException("Interest rate invalid");
        }
        this.interestRate = interestRate;
        log.fine(() -> "SavingsAccount body initialized rate=" + interestRate);
    }

    // CONVENIENCE constructor: chains via this(...) to the primary one,
    // defaulting the rate. Must be the first statement; cannot also call super.
    SavingsAccount(String accountId, String holderName, BigDecimal balance) {
        this(accountId, holderName, balance, DEFAULT_RATE);   // delegate within class
    }

    String describe() {
        return getAccountId() + " / " + getHolderName()
                + " / balance=" + getBalance() + " / rate=" + interestRate;
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
